import { z } from 'zod';
import { experimentKeySchema, paisaSchema } from '../catalog/catalog.contracts';
import { utmSchema } from '../orders/orders.contracts';

/** Client-side events (beacon). CHECKOUT and PURCHASE are derived server-side from order events. */
export const BEACON_EVENT_TYPES = ['VIEW', 'ADD_TO_CART'] as const;
export const TRACKED_EVENT_TYPES = ['VIEW', 'ADD_TO_CART', 'CHECKOUT', 'PURCHASE'] as const;
export type TrackedEventType = (typeof TRACKED_EVENT_TYPES)[number];

/** Anonymous per-browser id generated by the storefront (no personal data). */
export const sessionIdSchema = z.string().regex(/^[A-Za-z0-9_-]{16,64}$/);

export const beaconEventSchema = z.object({
  type: z.enum(BEACON_EVENT_TYPES),
  sessionId: sessionIdSchema,
  productId: z.uuid().optional(),
  variantId: z.uuid().optional(),
  /** Price experiment bucket the visitor saw (?p=a|b). */
  p: z.string().max(8).optional(),
  path: z.string().max(300).optional(),
  utm: utmSchema,
});
export type BeaconEvent = z.input<typeof beaconEventSchema>;

export const dashboardQuerySchema = z.object({
  from: z.iso.date().optional(),
  to: z.iso.date().optional(),
});
export type DashboardQuery = z.output<typeof dashboardQuerySchema>;

/** The pre-order GO threshold from docs/website-spec.md. */
export const GO_TARGET = 10;

export const dashboardStatsSchema = z.object({
  range: z.object({ from: z.string(), to: z.string() }),
  today: z.object({ orders: z.number().int(), revenuePaisa: paisaSchema }),
  /** Distinct sessions per stage (PURCHASE = confirmed orders linked to a session). */
  funnel: z.object({
    views: z.number().int(),
    addToCart: z.number().int(),
    checkout: z.number().int(),
    purchase: z.number().int(),
  }),
  revenueByDay: z.array(
    z.object({ date: z.string(), orders: z.number().int(), revenuePaisa: paisaSchema }),
  ),
  /** Non-friend B2C orders with a VERIFIED advance (paid pre-orders), still active. All time. */
  go: z.object({ count: z.number().int(), target: z.number().int(), reached: z.boolean() }),
  experiments: z.array(
    z.object({
      key: experimentKeySchema,
      sessions: z.number().int(),
      checkouts: z.number().int(),
      purchases: z.number().int(),
      conversionRate: z.number(),
    }),
  ),
  channels: z.object({
    b2c: z.object({ orders: z.number().int(), revenuePaisa: paisaSchema }),
    b2b: z.object({ orders: z.number().int(), revenuePaisa: paisaSchema }),
  }),
});
export type DashboardStats = z.infer<typeof dashboardStatsSchema>;
